// Python-compatible string case helpers.
// These mirror the exact semantics of CPython's str.lower/upper/title
// and str.islower/isupper/istitle for the cases the inflection code
// relies on (including mixed-case and non-letter boundaries).

function isCased(ch) {
  return ch.toLowerCase() !== ch.toUpperCase();
}

function isUpperChar(ch) {
  return isCased(ch) && ch === ch.toUpperCase();
}

function isLowerChar(ch) {
  return isCased(ch) && ch === ch.toLowerCase();
}

function isLetter(ch) {
  return /\p{L}/u.test(ch);
}

// str.islower(): at least one cased char, and every cased char is lowercase.
export function pyIsLower(s) {
  let any = false;
  for (const ch of s) {
    if (!isCased(ch)) continue;
    if (!isLowerChar(ch)) return false;
    any = true;
  }
  return any;
}

// str.isupper(): at least one cased char, and every cased char is uppercase.
export function pyIsUpper(s) {
  let any = false;
  for (const ch of s) {
    if (!isCased(ch)) continue;
    if (!isUpperChar(ch)) return false;
    any = true;
  }
  return any;
}

// str.istitle(): uppercase chars may only start a word (previous char
// uncased), lowercase chars may only follow a cased char.
export function pyIsTitle(s) {
  let any = false;
  let prevCased = false;
  for (const ch of s) {
    if (isUpperChar(ch)) {
      if (prevCased) return false;
      prevCased = true;
      any = true;
    } else if (isLowerChar(ch)) {
      if (!prevCased) return false;
      prevCased = true;
      any = true;
    } else {
      prevCased = false;
    }
  }
  return any;
}

// str.title(): uppercase the first letter of every word (words are runs
// of letters), lowercase the remaining letters of each word.
export function pyTitle(s) {
  let out = '';
  let prevLetter = false;
  for (const ch of s) {
    if (isLetter(ch)) {
      out += prevLetter ? ch.toLowerCase() : ch.toUpperCase();
      prevLetter = true;
    } else {
      out += ch;
      prevLetter = false;
    }
  }
  return out;
}

export function pyLower(s) {
  return s.toLowerCase();
}

export function pyUpper(s) {
  return s.toUpperCase();
}

// English noun inflection tables.
//
// These tables were reconstructed black-box from the reference behavior:
// whole-word lookups (uninflected words and irregular pairs) plus the
// small closed word lists that receive special suffix handling. Any word
// not listed here falls through to the generic suffix rules in
// inflect.mjs.

// Words whose plural is identical to the singular, plus plural forms that
// must not be re-pluralized (irregular plurals and the plural forms of
// the special lists below that do not already end in "es").
export const UNINFLECTED = new Set([
  // singular uninflected
  'bison', 'corps', 'deer', 'fish', 'means', 'moose', 'offspring',
  'scissors', 'series', 'sheep', 'species', 'formulas',
  // irregular plurals
  'people', 'men', 'women', 'children', 'feet', 'teeth', 'geese', 'mice',
  'lice', 'oxen', 'dice', 'corpora', 'firemen', 'milennia',
  // -us -> -i plurals
  'alumni', 'cacti', 'foci', 'fungi', 'hippopotami', 'nuclei', 'octopi',
  'radii', 'stimuli', 'syllabi',
  // -um -> -a plurals
  'addenda', 'bacteria', 'curricula', 'data', 'errata', 'media',
  'memoranda', 'ova', 'strata', 'symposia',
  // -on -> -a plurals
  'criteria', 'phenomena',
  // -a -> -ae plurals
  'algae', 'alumnae', 'antennae', 'nebulae', 'vertebrae',
]);

// Irregular singular -> plural pairs (whole-word matches only).
export const IRREGULAR_PLURALS = new Map([
  ['child', 'children'],
  ['corpus', 'corpora'],
  ['die', 'dice'],
  ['fireman', 'firemen'],
  ['foot', 'feet'],
  ['goose', 'geese'],
  ['louse', 'lice'],
  ['man', 'men'],
  ['millennium', 'milennia'],
  ['mouse', 'mice'],
  ['ox', 'oxen'],
  ['person', 'people'],
  ['tooth', 'teeth'],
  ['woman', 'women'],
]);

// -is -> -es  (analysis -> analyses)
export const IS_TO_ES = new Set([
  'analysis', 'axis', 'basis', 'crisis', 'diagnosis', 'ellipsis',
  'emphasis', 'hypothesis', 'neurosis', 'oasis', 'parenthesis',
  'synopsis', 'thesis',
]);

// -us -> -i  (cactus -> cacti)
export const US_TO_I = new Set([
  'alumnus', 'cactus', 'focus', 'fungus', 'hippopotamus', 'nucleus',
  'octopus', 'radius', 'stimulus', 'syllabus',
]);

// -um -> -a  (datum -> data)
export const UM_TO_A = new Set([
  'addendum', 'bacterium', 'curriculum', 'datum', 'erratum', 'medium',
  'memorandum', 'ovum', 'stratum', 'symposium',
]);

// -on -> -a  (criterion -> criteria)
export const ON_TO_A = new Set([
  'criterion', 'phenomenon',
]);

// -ex/-ix -> -ices  (index -> indices, matrix -> matrices)
export const EX_IX_TO_ICES = new Set([
  'appendix', 'index', 'matrix',
]);

// -a -> -ae  (alga -> algae)
export const A_TO_AE = new Set([
  'alga', 'alumna', 'antenna', 'nebula', 'vertebra',
]);

// -o -> -oes  (potato -> potatoes)
export const O_TO_OES = new Set([
  'echo', 'embargo', 'hero', 'mosquito', 'potato', 'tomato', 'torpedo',
  'veto',
]);

// -f -> -ves  (wolf -> wolves)
export const F_TO_VES = new Set([
  'calf', 'dwarf', 'elf', 'half', 'hoof', 'leaf', 'loaf', 'scarf', 'self',
  'shelf', 'thief', 'wolf',
]);

// -fe -> -ves  (knife -> knives)
export const FE_TO_VES = new Set([
  'knife', 'life', 'wife',
]);

// English noun inflection: pluralize / singularize / cardinalize / unit_len.
//
// Reimplemented black-box to match the reference behavior exactly:
//  - lookups and special word lists are whole-word matches on the
//    lowercased input;
//  - generic rules are suffix rules applied to the lowercased input;
//  - the case style of the original word is re-applied to the result
//    (all-upper -> upper, Title Case -> title, anything else -> lower);
//  - uninflected words are returned with their original casing untouched.

import { pyIsUpper, pyIsTitle, pyTitle, pyUpper } from './pystr.mjs';
import {
  UNINFLECTED,
  IRREGULAR_PLURALS,
  IS_TO_ES,
  US_TO_I,
  UM_TO_A,
  ON_TO_A,
  EX_IX_TO_ICES,
  A_TO_AE,
  O_TO_OES,
  F_TO_VES,
  FE_TO_VES,
} from './pluraldata.mjs';

function applyCaseStyle(original, lowerResult) {
  if (pyIsUpper(original)) return pyUpper(lowerResult);
  if (pyIsTitle(original)) return pyTitle(lowerResult);
  return lowerResult;
}

export function pluralize(word) {
  if (!word) return word;
  const lower = word.toLowerCase();

  if (UNINFLECTED.has(lower)) return word;

  let result;
  if (IRREGULAR_PLURALS.has(lower)) {
    result = IRREGULAR_PLURALS.get(lower);
  } else if (lower.endsWith('es')) {
    // Already-plural-looking words are left alone.
    result = lower;
  } else if (IS_TO_ES.has(lower)) {
    result = lower.slice(0, -2) + 'es';
  } else if (US_TO_I.has(lower)) {
    result = lower.slice(0, -2) + 'i';
  } else if (UM_TO_A.has(lower)) {
    result = lower.slice(0, -2) + 'a';
  } else if (ON_TO_A.has(lower)) {
    result = lower.slice(0, -2) + 'a';
  } else if (EX_IX_TO_ICES.has(lower)) {
    result = lower.slice(0, -2) + 'ices';
  } else if (A_TO_AE.has(lower)) {
    result = lower + 'e';
  } else if (O_TO_OES.has(lower)) {
    result = lower + 'es';
  } else if (F_TO_VES.has(lower)) {
    result = lower.slice(0, -1) + 'ves';
  } else if (FE_TO_VES.has(lower)) {
    result = lower.slice(0, -2) + 'ves';
  } else if (/[^aeiouy]y$/.test(lower)) {
    result = lower.slice(0, -1) + 'ies';
  } else if (/(?:s|sh|ch)$/.test(lower)) {
    result = lower + 'es';
  } else {
    result = lower + 's';
  }
  return applyCaseStyle(word, result);
}

// Matches the observed reference behavior: the singular form is returned
// unchanged for every input.
export function singularize(word) {
  return word;
}

export function cardinalize(unitNoun, count) {
  if (count === 1) return singularize(unitNoun);
  return pluralize(unitNoun);
}

export function unitLen(sized, unitNoun) {
  const count = sized.length;
  return `${count} ${cardinalize(unitNoun, count)}`;
}

// Minimal re-implementation of the argparse behavior used by the original
// script: two required string options (--a, --b) plus -h/--help, with
// matching usage/help text, error messages, and exit codes.

import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor() {
    this.prog = basename(process.argv[1] || 'test12.mjs');
    this.options = [];
  }

  addArgument(flag, { required = false, help = '' } = {}) {
    this.options.push({
      flag,
      metavar: flag.replace(/^-+/, '').toUpperCase(),
      required,
      help,
    });
  }

  formatUsage() {
    const parts = this.options.map((o) => `${o.flag} ${o.metavar}`);
    return `usage: ${this.prog} [-h] ${parts.join(' ')}`;
  }

  formatHelp() {
    const invocations = ['-h, --help'];
    const helps = ['show this help message and exit'];
    for (const o of this.options) {
      invocations.push(`${o.flag} ${o.metavar}`);
      helps.push(o.help);
    }
    const helpPos = 2 + Math.max(...invocations.map((s) => s.length)) + 2;
    const lines = invocations.map(
      (inv, i) => '  ' + inv.padEnd(helpPos - 2) + helps[i],
    );
    return `${this.formatUsage()}\n\noptions:\n${lines.join('\n')}\n`;
  }

  error(message) {
    process.stderr.write(`${this.formatUsage()}\n${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv = process.argv.slice(2)) {
    const byFlag = new Map(this.options.map((o) => [o.flag, o]));
    const values = new Map();
    const extras = [];
    let sawSeparator = false;

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      if (sawSeparator) {
        extras.push(token);
        continue;
      }
      if (token === '--') {
        sawSeparator = true;
        continue;
      }
      if (token === '-h' || token === '--help') {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }
      let flag = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const eq = token.indexOf('=');
        flag = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }
      const opt = byFlag.get(flag);
      if (opt) {
        if (inlineValue !== null) {
          values.set(opt.flag, inlineValue);
        } else {
          const next = argv[i + 1];
          const looksLikeOption =
            next !== undefined &&
            next.length > 1 &&
            next.startsWith('-') &&
            !NEGATIVE_NUMBER.test(next);
          if (next === undefined || looksLikeOption) {
            this.error(`argument ${opt.flag}: expected one argument`);
          }
          values.set(opt.flag, next);
          i++;
        }
      } else {
        extras.push(token);
      }
    }

    const missing = this.options
      .filter((o) => o.required && !values.has(o.flag))
      .map((o) => o.flag);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const result = {};
    for (const o of this.options) {
      const key = o.flag.replace(/^-+/, '');
      result[key] = values.get(o.flag);
    }
    return result;
  }
}

